import sys,numpy as np
from scipy.spatial.transform import Rotation as R
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot();n=np.array(r.get_obs(video='none').meta['proprio']['now']);base=R.from_euler('x',90,degrees=True)*R.from_quat([-.707,.707,0,0]);best=[]
for x in [.55,.6,.65]:
 for z in [.10,.13,.16]:
  for deg in range(0,360,45):
   q=(base*R.from_euler('z',deg,degrees=True)).as_quat();Q=[q[3],*q[:3]]
   for y in [-.25,-.35,-.45,-.5]:
    k=r.ik({'tcp':[x,y,z,*Q]},seed=n[:7]);
    if k['ok']:best.append((x,z,deg,y))
print('feasible',len(best))
for x in [.55,.6,.65]:
 for z in [.10,.13,.16]:
  a=[b for b in best if b[0]==x and b[1]==z]
  if a:print(x,z,'max',min(b[3] for b in a),'angles',sorted(set((b[2],b[3]) for b in a if b[3]==min(v[3] for v in a))))
